dt::IntervalMetricEvidenceV3 Evidence(const EvidenceSpec& value) {
  return {value.evidence_type, value.metric, value.event, value.database,
          value.node, value.epoch, value.sequence, value.timestamp, value.delta,
          {static_cast<dt::IntervalMetricOperationV3>(value.operation),
           static_cast<dt::IntervalMetricSourceFamilyV3>(value.source),
           static_cast<dt::IntervalMetricStateV3>(value.state),
           static_cast<dt::IntervalMetricReasonV3>(value.reason)},
          value.committed, value.fields, value.scalars};
}

void RouteTable() {
  const auto routes = dt::IntervalDiagnosticMetricRoutesV3();
  Check(routes.size() == kRoutes.size(), "route row count");
  for (std::size_t index = 0; index < kRoutes.size(); ++index) {
    current_case = static_cast<unsigned>(index);
    const auto& actual = routes[index]; const auto& expected = kRoutes[index];
    Check(static_cast<unsigned>(actual.key.axis) == expected.axis && actual.key.diagnostic_uuid == expected.diagnostic,
          "route key and order");
    Check(static_cast<unsigned>(actual.type) == expected.type && actual.metric_uuid == expected.metric,
          "route metric identity");
    Check(actual.canonical_name == expected.name && actual.permitted_operation_mask == expected.operations &&
          actual.permitted_source_family_mask == expected.sources && actual.permitted_state_mask == expected.states &&
          static_cast<unsigned>(actual.reason) == expected.reason, "route payload");
  }
  std::vector<dt::IntervalDiagnosticMetricRouteV3> supplied(routes.begin(), routes.end());
  Check(dt::ValidateIntervalDiagnosticMetricRouteTableV3(supplied) == dt::IntervalDiagnosticMetricRouteDispositionV3::admitted, "route exact");
  supplied.pop_back();
  Check(dt::ValidateIntervalDiagnosticMetricRouteTableV3(supplied) == dt::IntervalDiagnosticMetricRouteDispositionV3::missing, "route missing");
  supplied.assign(routes.begin(), routes.end()); supplied.back().key.diagnostic_uuid = Id(0xfe);
  Check(dt::ValidateIntervalDiagnosticMetricRouteTableV3(supplied) == dt::IntervalDiagnosticMetricRouteDispositionV3::unknown, "route unknown");
  Check(dt::ValidateIntervalDiagnosticMetricRouteTableV3(routes, false) == dt::IntervalDiagnosticMetricRouteDispositionV3::wrong_type, "route wrong scalar type");
  supplied.assign(routes.begin(), routes.end()); std::swap(supplied[0], supplied[1]);
  Check(dt::ValidateIntervalDiagnosticMetricRouteTableV3(supplied) == dt::IntervalDiagnosticMetricRouteDispositionV3::reordered, "route reordered");
  supplied.assign(routes.begin(), routes.end()); supplied.back() = supplied.front();
  Check(dt::ValidateIntervalDiagnosticMetricRouteTableV3(supplied) == dt::IntervalDiagnosticMetricRouteDispositionV3::duplicate, "route duplicate");
}

void DiagnosticRouteExecution() {
  using K = dt::IntervalDiagnosticParameterKindV3;
  struct Schema { std::array<std::string_view, 5> names; std::array<K, 5> kinds; unsigned count; };
  const std::array<Schema, 15> schemas{{
    {{{"input_extent_u32","failure_offset_u32","reason_enum"}},{{K::unsigned_u64,K::unsigned_u64,K::token}},3},
    {{{"receipt_uuid","catalog_generation_u64","registry_generation_u64","identity_kind_enum"}},{{K::uuid,K::unsigned_u64,K::unsigned_u64,K::token}},4},
    {{{"extent_u64","offset_u64","reason_enum"}},{{K::unsigned_u64,K::unsigned_u64,K::token}},3},
    {{{"source_type_uuid","target_type_uuid","cast_context_enum","reason_enum"}},{{K::uuid,K::uuid,K::token,K::token}},4},
    {{{"component_enum","extent_u64","required_extent_u64","reason_enum"}},{{K::token,K::unsigned_u64,K::unsigned_u64,K::token}},4},
    {{{"operation_enum","reason_enum"}},{{K::token,K::token}},2},
    {{{"operation_enum","component_enum","reason_enum"}},{{K::token,K::token,K::token}},3},
    {{{"operation_enum","required_extent_u64","available_extent_u64","checkpoint_enum"}},{{K::token,K::unsigned_u64,K::unsigned_u64,K::token}},4},
    {{{"protection_mode_enum","extent_u64","reason_enum"}},{{K::token,K::unsigned_u64,K::token}},3},
    {{{"protection_mode_enum","authorization_state_enum","reason_enum"}},{{K::token,K::token,K::token}},3},
    {{{"lane_enum","direction_enum","extent_u64","offset_u64","reason_enum"}},{{K::token,K::token,K::unsigned_u64,K::unsigned_u64,K::token}},5},
    {{{"index_family_enum","operation_enum","reason_enum"}},{{K::token,K::token,K::token}},3},
    {{{"state_enum","operation_enum","reason_enum"}},{{K::token,K::token,K::token}},3},
    {{{"extent_u64","offset_u64","reason_enum"}},{{K::unsigned_u64,K::unsigned_u64,K::token}},3},
    {{{"statistics_uuid","source_object_uuid","provider_evidence_uuid","epoch_kind_enum"}},{{K::uuid,K::uuid,K::uuid,K::token}},4}}};
  const std::array<std::string_view, 37> codes{{
    "SBLR.OPERAND_INVALID","CTI.TEMPORAL.INVALID_LITERAL","SECURITY.ACCESS_DENIED","CTI.INTERVAL.DESCRIPTOR_INVALID",
    "CTI.INTERVAL.SUBTYPE_MISMATCH","STORAGE.PAGE_CHECKSUM_FAILED","CTI.TEMPORAL.CANONICAL_ENCODING_INVALID",
    "DATATYPE.CAST_FORBIDDEN","CTI.TEMPORAL.INVALID_LITERAL","CTI.TEMPORAL.RANGE_EXCEEDED","CTB.TEXT.LENGTH_EXCEEDED",
    "CTI.INTERVAL.CALENDAR_OPERATION_REFUSED","CTI.TEMPORAL.ORDERING_REFUSED","CTI.TEMPORAL.RANGE_EXCEEDED",
    "RESOURCE.BUDGET_EXCEEDED","PROCESS.CANCELLED","CTI.TEMPORAL.PROTECTION_UNSUPPORTED",
    "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID","SECURITY.ACCESS_DENIED","CTI.TEMPORAL.PROTECTION_UNSUPPORTED",
    "SBLR.OPERAND_INVALID","SBLR.ENVELOPE.CHECKSUM_INVALID","CTI.TEMPORAL.CANONICAL_ENCODING_INVALID",
    "CTI.TEMPORAL.SERIALIZATION_PROFILE_MISSING","CTI.TRANSPORT.UNSUPPORTED","CTI.TEMPORAL.ORDERING_REFUSED",
    "OPTIMIZER.INDEX_COMPATIBILITY_MISSING","CTI.TEMPORAL.INDEX_KEY_REFUSED","DATATYPE.NULL_STATE.INVALID",
    "DATATYPE.NULL_NOT_ADMITTED","DOMAIN.CONSTRAINT_FAILED","STORAGE.PAGE_CHECKSUM_FAILED",
    "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID","CTI.MERGE.MANUAL_REVIEW_REQUIRED","SECURITY.ACCESS_DENIED",
    "OPTIMIZER.STATISTICS_PRIVACY_DENIED","OPTIMIZER.STATISTICS_EPOCH_MISMATCH"}};
  const std::array<std::string_view, 9> forbidden{{"component_value","canonical_text","encoded_bytes","raw_bytes",
      "hash_preimage","secret","address","diagnostic_prose","reference_engine_name"}};
  const std::array<unsigned, 15> disposition{{0,1,3,4,6,7,2,2,2,2,2,2,2,2,2}};
  unsigned five_parameter_wire_cases = 0;
  for (unsigned route = 0; route < 37; ++route) {
    const auto axis = kRoutes[route].axis; const auto& schema = schemas[axis];
    const auto published_schema = dt::IntervalDiagnosticParameterSchemaV3(static_cast<dt::IntervalDiagnosticAxisV3>(axis));
    Check(published_schema.size() == schema.count, "diagnostic schema count");
    for (unsigned index = 0; index < schema.count; ++index)
      Check(published_schema[index].name == schema.names[index] && published_schema[index].kind == schema.kinds[index],
            "diagnostic literal schema");
    if (axis == 10) { Check(schema.count == 5, "wire five parameter schema"); ++five_parameter_wire_cases; }
    for (unsigned mutation = 0; mutation < 15; ++mutation) {
      current_case = route * 15 + mutation;
      std::array<dt::IntervalDiagnosticParameterV3, 6> parameters{};
      for (unsigned index = 0; index < schema.count; ++index) {
        parameters[index].name = schema.names[index]; parameters[index].kind = schema.kinds[index];
        parameters[index].unsigned_value = 1; parameters[index].signed_value = 1;
        parameters[index].uuid_value = Id(static_cast<p::byte>(index + 1)); parameters[index].token_value = "validation_failure";
      }
      unsigned count = schema.count; bool in_range = true; auto diagnostic_uuid = kRoutes[route].diagnostic;
      if (mutation == 1) diagnostic_uuid = {};
      else if (mutation == 2) --count;
      else if (mutation == 3) { parameters[count].name = "undeclared_token"; parameters[count].kind = K::unsigned_u64; ++count; }
      else if (mutation == 4) parameters[0].kind = parameters[0].kind == K::uuid ? K::token : K::uuid;
      else if (mutation == 5) in_range = false;
      else if (mutation >= 6) { parameters[count].name = forbidden[mutation - 6]; parameters[count].kind = K::token; parameters[count].token_value = "REDACTED_TEST_VALUE"; ++count; }
      const auto actual = dt::ValidateIntervalDiagnosticEmissionV3({
        {static_cast<dt::IntervalDiagnosticAxisV3>(axis), kRoutes[route].diagnostic}, codes[route], diagnostic_uuid,
        std::span<const dt::IntervalDiagnosticParameterV3>(parameters.data(), count), in_range});
      Check(static_cast<unsigned>(actual.disposition) == disposition[mutation], "555 diagnostic route disposition");
      Check(actual.diagnostic_emission_admitted == (mutation == 0) &&
            actual.diagnostic_parameter_publication_admitted == (mutation == 0), "diagnostic publication atomicity");
      Check(actual.parameters_validated == (mutation == 0 ? schema.count : 0), "diagnostic validated parameter count");
    }
  }
  Check(five_parameter_wire_cases == 5, "five wire five-parameter routes");
}

void MetricProductionAndValidation(const dt::IntervalValidatedProfileHandleV3& good) {
  const auto routes = dt::IntervalDiagnosticMetricRoutesV3();
  for (std::size_t ordinal = 0; ordinal < kValidTuples.size(); ++ordinal) {
    current_case = static_cast<unsigned>(ordinal);
    const auto& tuple = kValidTuples[ordinal]; const auto& route = routes[tuple.route];
    dt::IntervalMetricClosedLabelTupleV3 labels{
      static_cast<dt::IntervalMetricOperationV3>(tuple.operation),
      static_cast<dt::IntervalMetricSourceFamilyV3>(tuple.source),
      static_cast<dt::IntervalMetricStateV3>(tuple.state), route.reason};
    Check(dt::IsIntervalMetricLabelTupleAdmittedV3(route, labels), "literal valid tuple admitted");
  }
  Check(!dt::IsIntervalMetricLabelTupleAdmittedV3(routes[0],
        {dt::IntervalMetricOperationV3::cast, dt::IntervalMetricSourceFamilyV3::native_character,
         dt::IntervalMetricStateV3::present, dt::IntervalMetricReasonV3::success}), "success label forbidden");

  for (std::size_t ordinal = 0; ordinal < kProduction.size(); ++ordinal) {
    current_case = static_cast<unsigned>(ordinal);
    const auto& expected = kProduction[ordinal];
    auto profile = good;
    if (!expected.profile_valid) profile.profile_fingerprint[0] ^= 1;
    dt::IntervalMetricEvidenceProductionRequestV3 request;
    request.selected_final_diagnostic = {static_cast<dt::IntervalDiagnosticAxisV3>(expected.axis), expected.diagnostic};
    request.source_event_uuid = expected.event; request.database_uuid = expected.database; request.node_uuid = expected.node;
    request.process_epoch = expected.epoch; request.event_sequence = expected.sequence; request.monotonic_timestamp_ns = expected.timestamp;
    request.operation = static_cast<dt::IntervalMetricOperationV3>(expected.operation);
    request.source_family = static_cast<dt::IntervalMetricSourceFamilyV3>(expected.source);
    request.state = static_cast<dt::IntervalMetricStateV3>(expected.state);
    const auto allocation_count = allocation_probe::calls;
    const auto actual = dt::ProduceIntervalMetricEvidenceV3(profile, request);
    Check(allocation_probe::calls == allocation_count, "metric production is allocation-free");
    Check(static_cast<unsigned>(actual.disposition) == expected.disposition, expected.id);
    Check(actual.receiving_owner_evidence_handoff_ready == (expected.disposition == 0) && !actual.metric_mutation_admitted &&
          actual.datatype_outcome_unchanged && actual.metric_outcome_unchanged, "production publication facts");
    if (expected.disposition == 0) {
      const auto route = std::find_if(kRoutes.begin(), kRoutes.end(), [&](const RouteExpected& candidate) {
        return candidate.axis == expected.axis && candidate.diagnostic == expected.diagnostic;
      });
      Check(route != kRoutes.end(), "production route exists in literal Core table");
      Check(actual.evidence.evidence_type_uuid == route->metric && actual.evidence.metric_uuid == route->metric &&
            actual.evidence.source_event_uuid == expected.event && actual.evidence.database_uuid == expected.database &&
            actual.evidence.node_uuid == expected.node && actual.evidence.process_epoch == expected.epoch &&
            actual.evidence.event_sequence == expected.sequence && actual.evidence.monotonic_timestamp_ns == expected.timestamp &&
            actual.evidence.counter_delta == 1 && actual.evidence.labels.operation == request.operation &&
            actual.evidence.labels.source_family == request.source_family && actual.evidence.labels.state == request.state &&
            static_cast<unsigned>(actual.evidence.labels.reason) == route->reason && actual.evidence.outcome_committed &&
            actual.evidence.all_required_fields_present && actual.evidence.scalar_types_valid, "production exact evidence");
    } else {
      Check(actual.evidence == dt::IntervalMetricEvidenceV3{}, "production refusal publishes empty evidence");
    }
  }

  for (std::size_t ordinal = 0; ordinal < kValidation.size(); ++ordinal) {
    current_case = static_cast<unsigned>(ordinal);
    const auto& expected = kValidation[ordinal]; auto profile = good;
    if (!expected.profile_valid) profile.profile_fingerprint[0] ^= 1;
    const auto actual = dt::ValidateIntervalMetricEvidenceV3(
      profile, {static_cast<dt::IntervalDiagnosticAxisV3>(expected.axis), expected.diagnostic},
      Evidence(expected.evidence), {expected.current_epoch, expected.current_counter});
    Check(static_cast<unsigned>(actual.disposition) == expected.disposition, expected.id);
    Check(actual.receiving_owner_update_admitted == expected.update && actual.datatype_outcome_unchanged &&
          actual.metric_outcome_unchanged, "validation publication facts");
    if (!expected.update) Check(actual.idempotency.source_event_uuid.is_nil(), "validation refusal publishes no idempotency fact");
  }
}

void Replay() {
  for (std::size_t ordinal = 0; ordinal < kReplay.size(); ++ordinal) {
    current_case = static_cast<unsigned>(ordinal);
    const auto& expected = kReplay[ordinal];
    const auto actual = dt::ClassifyIntervalMetricReplayV3(Evidence(expected.first), Evidence(expected.second));
    Check(static_cast<unsigned>(actual.disposition) == expected.disposition, expected.id);
    Check(actual.second_emission_admitted == expected.second_emission &&
          actual.receiving_owner_update_admitted == expected.owner_update &&
          actual.idempotent_without_increment == expected.idempotent &&
          actual.datatype_outcome_unchanged && actual.metric_outcome_unchanged, "replay exact facts");
  }
  const auto types = dt::IntervalMetricEvidenceTypesV3();
  Check(types.size() == 5, "five evidence types");
  const std::array<unsigned, 25> expected{{1,3,3,3,3, 3,1,3,3,3, 3,3,1,3,3, 3,3,3,1,3, 3,3,3,3,1}};
  for (unsigned left = 0; left < 5; ++left) for (unsigned right = 0; right < 5; ++right) {
    current_case = left * 5 + right;
    dt::IntervalMetricEvidenceV3 a, b;
    a.evidence_type_uuid = a.metric_uuid = types[left].metric_uuid;
    b.evidence_type_uuid = b.metric_uuid = types[right].metric_uuid;
    a.source_event_uuid = b.source_event_uuid = Id(1); a.database_uuid = b.database_uuid = Id(2); a.node_uuid = b.node_uuid = Id(3);
    a.process_epoch = b.process_epoch = 7; a.event_sequence = b.event_sequence = 1;
    a.monotonic_timestamp_ns = b.monotonic_timestamp_ns = 100; a.counter_delta = b.counter_delta = 1;
    a.labels = b.labels = {dt::IntervalMetricOperationV3::validate, dt::IntervalMetricSourceFamilyV3::native_value,
                            dt::IntervalMetricStateV3::present, dt::IntervalMetricReasonV3::descriptor_invalid};
    a.outcome_committed = b.outcome_committed = true;
    const auto actual = dt::ClassifyIntervalMetricReplayV3(a, b);
    Check(static_cast<unsigned>(actual.disposition) == expected[left * 5 + right], "25-cell same-source matrix");
  }
}

void Wire(const dt::IntervalValidatedProfileHandleV3& profile) {
  for (unsigned lane = 0; lane < 27; ++lane) {
    const auto expected_lane = static_cast<dt::IntervalWireLaneV3>(lane);
    const bool expected_mapping = lane < 3;
    const std::string_view lane_disposition = expected_mapping
        ? "unsupported_current_outer_version_unallocated"
        : "unsupported_no_manifest_listed_compatibility_profile";
    for (unsigned mutation = 0; mutation < 9; ++mutation) {
      current_case = lane * 9 + mutation;
      auto supplied_profile = profile;
      dt::IntervalWireLaneRequestV3 request{&profile, expected_lane, expected_lane,
          expected_mapping, dt::IntervalWireAttemptKindV3::capability_query};
      std::string_view expected_disposition = lane_disposition;
      std::string_view expected_diagnostic = "CTI.TRANSPORT.UNSUPPORTED";
      if (mutation == 1) {
        supplied_profile.receipt.statement_receipt_uuid = Id(0xe1);
        request.profile_handle = &supplied_profile;
        expected_disposition = "profile_invalid";
        expected_diagnostic = "CTI.INTERVAL.DESCRIPTOR_INVALID";
      } else if (mutation == 2) {
        supplied_profile.profile_fingerprint[0] ^= 1;
        supplied_profile.profile_material[0] ^= 1;
        request.profile_handle = &supplied_profile;
        expected_disposition = "profile_invalid";
        expected_diagnostic = "CTI.INTERVAL.DESCRIPTOR_INVALID";
      } else if (mutation == 3) {
        request.supplied_lane = static_cast<dt::IntervalWireLaneV3>(255);
        expected_disposition = "supplied_lane_mismatch";
      } else if (mutation == 4) {
        request.attempt = dt::IntervalWireAttemptKindV3::outer_version;
      } else if (mutation == 5) {
        request.supplied_component_mapping_complete = !expected_mapping;
        expected_disposition = "component_mapping_mismatch";
      } else if (mutation == 6) {
        request.attempt = dt::IntervalWireAttemptKindV3::admission;
      } else if (mutation == 7) {
        request.attempt = dt::IntervalWireAttemptKindV3::typed_null;
      } else if (mutation == 8) {
        request.attempt = dt::IntervalWireAttemptKindV3::present;
      }
      const auto actual = dt::ResolveIntervalWireLaneV3(request);
      Check(actual.lane == expected_lane && actual.component_mapping_complete == expected_mapping,
            "wire retains expected lane and mapping");
      Check(!actual.admitted && actual.receiving_owner_handoff && actual.disposition == expected_disposition &&
            actual.diagnostic == expected_diagnostic, "27x9 wire request corpus");
    }
  }
  auto request = dt::IntervalWireLaneRequestV3{};
  request.profile_handle = nullptr;
  auto actual = dt::ResolveIntervalWireLaneV3(request);
  Check(actual.disposition == "profile_missing" && actual.diagnostic == "CTI.INTERVAL.DESCRIPTOR_INVALID", "wire missing profile");
  request.profile_handle = &profile; request.expected_lane = static_cast<dt::IntervalWireLaneV3>(255);
  request.supplied_lane = request.expected_lane; request.supplied_component_mapping_complete = false;
  actual = dt::ResolveIntervalWireLaneV3(request);
  Check(actual.lane == request.expected_lane && !actual.component_mapping_complete &&
        actual.disposition == "unknown_expected_lane_fail_closed" && actual.diagnostic == "CTI.TRANSPORT.UNSUPPORTED", "wire unknown expected lane");
  request.expected_lane = dt::IntervalWireLaneV3::native_sbwp; request.supplied_lane = request.expected_lane;
  request.supplied_component_mapping_complete = true; request.attempt = static_cast<dt::IntervalWireAttemptKindV3>(255);
  actual = dt::ResolveIntervalWireLaneV3(request);
  Check(actual.disposition == "unknown_attempt_fail_closed" && actual.diagnostic == "CTI.TRANSPORT.UNSUPPORTED", "wire unknown attempt");
}

void Protection(const dt::IntervalValidatedProfileHandleV3& profile) {
  struct Cell { bool admitted, handoff; std::string_view disposition, diagnostic; };
  const std::array<Cell, 10> expected{{
    {true,false,"admitted_datatype_component",{}},
    {false,false,"forbidden","CTI.TEMPORAL.PROTECTION_UNSUPPORTED"},
    {false,false,"forbidden","CTI.TEMPORAL.PROTECTION_UNSUPPORTED"},
    {false,true,"receiving_owner_handoff",{}}, {false,true,"receiving_owner_handoff",{}},
    {false,true,"receiving_owner_handoff",{}}, {false,true,"receiving_owner_handoff",{}},
    {false,true,"receiving_owner_handoff",{}}, {false,true,"receiving_owner_handoff",{}},
    {false,false,"forbidden","CTI.TEMPORAL.PROTECTION_UNSUPPORTED"}}};
  for (unsigned ordinal = 0; ordinal < expected.size(); ++ordinal) {
    current_case = ordinal; const auto actual = dt::ResolveIntervalProtectionV3(static_cast<dt::IntervalProtectionCellV3>(ordinal));
    Check(actual.cell == static_cast<dt::IntervalProtectionCellV3>(ordinal) && actual.datatype_admitted == expected[ordinal].admitted &&
          actual.receiving_owner_handoff == expected[ordinal].handoff && actual.disposition == expected[ordinal].disposition &&
          actual.diagnostic == expected[ordinal].diagnostic, "10 protection cells");
  }
  for (unsigned storage = 0; storage < 4; ++storage) for (unsigned stream = 0; stream < 4; ++stream) for (unsigned index = 0; index < 2; ++index) {
    current_case = storage * 8 + stream * 2 + index; const bool admitted = storage == 0 && stream == 0;
    const auto actual = dt::AdmitIntervalProtectionCombinationV3(profile,
      static_cast<dt::IntervalProtectionModeV3>(storage), static_cast<dt::IntervalProtectionModeV3>(stream),
      static_cast<dt::IntervalProtectionIndexModeV3>(index));
    Check(actual.storage_mode == static_cast<dt::IntervalProtectionModeV3>(storage) &&
          actual.stream_mode == static_cast<dt::IntervalProtectionModeV3>(stream) &&
          actual.index_mode == static_cast<dt::IntervalProtectionIndexModeV3>(index) && actual.admitted == admitted &&
          actual.disposition == (admitted ? "admitted" : "refused") &&
          actual.diagnostic == (admitted ? std::string_view{} : "CTI.TEMPORAL.PROTECTION_UNSUPPORTED"), "32 protection combinations");
  }
  auto wrong_profile = profile; wrong_profile.profile_fingerprint[0] ^= 1;
  auto mutation = dt::AdmitIntervalProtectionCombinationV3(wrong_profile, dt::IntervalProtectionModeV3::clear,
      dt::IntervalProtectionModeV3::clear, dt::IntervalProtectionIndexModeV3::not_indexed);
  Check(!mutation.admitted && mutation.diagnostic == "CTI.INTERVAL.DESCRIPTOR_INVALID", "mutation wrong profile");
  auto wrong_policy = profile; wrong_policy.protection_policy.uuid = Id(0xee);
  mutation = dt::AdmitIntervalProtectionCombinationV3(wrong_policy, dt::IntervalProtectionModeV3::clear,
      dt::IntervalProtectionModeV3::clear, dt::IntervalProtectionIndexModeV3::not_indexed);
  Check(!mutation.admitted && mutation.diagnostic == "CTI.INTERVAL.DESCRIPTOR_INVALID", "mutation wrong protection policy");
  auto historical = profile; historical.receipt.statement_receipt_uuid = Id(0xed);
  mutation = dt::AdmitIntervalProtectionCombinationV3(historical, dt::IntervalProtectionModeV3::clear,
      dt::IntervalProtectionModeV3::clear, dt::IntervalProtectionIndexModeV3::not_indexed);
  Check(!mutation.admitted && mutation.diagnostic == "CTI.INTERVAL.DESCRIPTOR_INVALID", "mutation historical receipt");
  const auto protected_index = dt::ResolveIntervalProtectionV3(dt::IntervalProtectionCellV3::protected_index);
  Check(!protected_index.datatype_admitted && protected_index.diagnostic == "CTI.TEMPORAL.PROTECTION_UNSUPPORTED", "mutation protected index");
  mutation = dt::ResolveIntervalProtectionCombinationV3(static_cast<dt::IntervalProtectionModeV3>(255),
      dt::IntervalProtectionModeV3::clear, dt::IntervalProtectionIndexModeV3::not_indexed);
  Check(!mutation.admitted && mutation.diagnostic == "CTI.INTERVAL.DESCRIPTOR_INVALID", "mutation unknown enum");
}

void PinnedReaders(const std::shared_ptr<const dt::IntervalValidatedProfileHandleV3>& profile) {
  const auto value = Value(profile); std::atomic<unsigned> failures{0}; std::vector<std::thread> readers;
  for (unsigned thread = 0; thread < 8; ++thread) readers.emplace_back([&, profile, value] {
    for (unsigned iteration = 0; iteration < 4096; ++iteration) {
      const auto valid = dt::ValidateIntervalProfileHandleV3(*profile); const auto hash = dt::HashIntervalValueV3(value);
      if (!valid.ok() || !hash.ok() || hash.bytes.size() != 32) ++failures;
    }
  });
  for (auto& reader : readers) reader.join();
  Check(failures == 0, "eight pinned readers x 4096");
}

struct ScrubTracker {
  std::array<unsigned, 31> count{};
  std::array<std::uint64_t, 31> extent{};
  bool all_zero = true;
};
static_assert(static_cast<unsigned>(dt::IntervalScrubClassV3::count) == 31);
void ObserveScrub(void* context, dt::IntervalScrubClassV3 which, const p::byte* bytes, p::u64 extent) noexcept {
  auto& tracker = *static_cast<ScrubTracker*>(context); const auto ordinal = static_cast<unsigned>(which);
  if (ordinal >= 31) { tracker.all_zero = false; return; }
  ++tracker.count[ordinal]; tracker.extent[ordinal] += extent;
  if (extent == 0 || bytes == nullptr) tracker.all_zero = false;
  for (p::u64 index = 0; index < extent; ++index) if (bytes[index] != 0) tracker.all_zero = false;
}

struct CancelState { unsigned calls = 0, cancel_at = 0; };
bool CancelAt(void* context) noexcept { auto& state = *static_cast<CancelState*>(context); return ++state.calls == state.cancel_at; }
dt::IntervalExecutionControlV3 CancelFinal(unsigned checkpoint, CancelState& state) {
  state = {0, checkpoint}; dt::IntervalExecutionControlV3 control; control.cancelled = CancelAt; control.cancellation_context = &state; return control;
}

void ResourceAtomicity(const std::shared_ptr<const dt::IntervalValidatedProfileHandleV3>& profile) {
  auto constructed = dt::ConstructIntervalV3(profile, std::numeric_limits<std::int32_t>::min(),
      std::numeric_limits<std::int32_t>::min(), std::numeric_limits<std::int64_t>::min());
  Check(constructed.ok(), "construct maximum text extent value");
  const auto value = std::move(constructed.value);
  std::array<p::byte, 32> hash; hash.fill(0xa5); const auto hash_before = hash;
  auto write = dt::HashIntervalValueIntoNoAllocV3(value, hash.data(), 31);
  Check(!write.ok() && Diagnostic(write, "RESOURCE.BUDGET_EXCEEDED") && write.bytes_required == 32 && write.bytes_written == 0 && hash == hash_before,
        "hash one short unchanged");
  const auto hash_allocations = allocation_probe::calls;
  write = dt::HashIntervalValueIntoNoAllocV3(value, hash.data(), 32);
  Check(write.ok() && write.bytes_required == 32 && write.bytes_written == 32 &&
        allocation_probe::calls == hash_allocations, "hash exact capacity and zero allocations");
  CancelState cancel; auto control = CancelFinal(1, cancel); hash.fill(0xa5);
  write = dt::HashIntervalValueIntoNoAllocV3(value, hash.data(), 32, control);
  Check(!write.ok() && Diagnostic(write, "PROCESS.CANCELLED") && write.bytes_written == 0 && hash == hash_before, "hash final cancel unchanged");

  std::array<p::byte, 16> component; component.fill(0xa5); const auto component_before = component;
  write = dt::EncodeCanonicalIntervalComponentIntoNoAllocV3(value, component.data(), 15);
  Check(!write.ok() && Diagnostic(write, "RESOURCE.BUDGET_EXCEEDED") && write.bytes_required == 16 && write.bytes_written == 0 && component == component_before,
        "component one short unchanged");
  const auto component_allocations = allocation_probe::calls;
  write = dt::EncodeCanonicalIntervalComponentIntoNoAllocV3(value, component.data(), 16);
  Check(write.ok() && write.bytes_required == 16 && write.bytes_written == 16 &&
        allocation_probe::calls == component_allocations, "component exact capacity and zero allocations");
  control = CancelFinal(1, cancel); component.fill(0xa5);
  write = dt::EncodeCanonicalIntervalComponentIntoNoAllocV3(value, component.data(), 16, control);
  Check(!write.ok() && Diagnostic(write, "PROCESS.CANCELLED") && write.bytes_written == 0 && component == component_before,
        "component final cancel unchanged");
  std::array<p::byte, 15> truncated{};
  auto decoded = dt::DecodeCanonicalIntervalComponentNoAllocV3(*profile, dt::IntervalValueStateV3::value, true, truncated);
  Check(!decoded.ok() && Diagnostic(decoded, "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID") && decoded.value.profile == nullptr,
        "component decode invalid extent no publication");
  control = CancelFinal(1, cancel);
  decoded = dt::DecodeCanonicalIntervalComponentNoAllocV3(*profile, dt::IntervalValueStateV3::value, true, component, control);
  Check(!decoded.ok() && Diagnostic(decoded, "PROCESS.CANCELLED") && decoded.value.profile == nullptr, "component decode final cancel no publication");

  auto rendered = dt::RenderCanonicalIntervalV3(value); Check(rendered.ok() && rendered.text.size() == 63, "render maximum extent source");
  std::array<char, 63> text; text.fill(static_cast<char>(0xa5)); const auto text_before = text;
  write = dt::RenderCanonicalIntervalIntoNoAllocV3(value, text.data(), rendered.text.size() - 1);
  Check(!write.ok() && Diagnostic(write, "CTB.TEXT.LENGTH_EXCEEDED") && write.bytes_written == 0 && text == text_before, "render one short unchanged");
  const auto render_allocations = allocation_probe::calls;
  write = dt::RenderCanonicalIntervalIntoNoAllocV3(value, text.data(), rendered.text.size());
  Check(write.ok() && write.bytes_written == 63 && allocation_probe::calls == render_allocations,
        "render exact capacity and zero allocations");
  control = CancelFinal(1, cancel); text.fill(static_cast<char>(0xa5));
  write = dt::RenderCanonicalIntervalIntoNoAllocV3(value, text.data(), rendered.text.size(), control);
  Check(!write.ok() && Diagnostic(write, "PROCESS.CANCELLED") && write.bytes_written == 0 && text == text_before, "render final cancel unchanged");
  const std::string overlong(64, '0');
  auto parsed = dt::ParseCanonicalIntervalV3(profile, overlong);
  Check(!parsed.ok() && Diagnostic(parsed, "CTB.TEXT.LENGTH_EXCEEDED") && parsed.value.profile == nullptr, "parse over maximum no publication");
  parsed = dt::ParseCanonicalIntervalV3(profile, rendered.text);
  Check(parsed.ok() && parsed.value.months == std::numeric_limits<std::int32_t>::min() &&
        parsed.value.civil_days == std::numeric_limits<std::int32_t>::min() &&
        parsed.value.fixed_nanoseconds == std::numeric_limits<std::int64_t>::min(), "parse exact maximum extent");
  control = CancelFinal(1, cancel); parsed = dt::ParseCanonicalIntervalV3(profile, rendered.text, true, control);
  Check(!parsed.ok() && Diagnostic(parsed, "PROCESS.CANCELLED") && parsed.value.profile == nullptr, "parse final cancel no publication");

  auto* object_bytes = reinterpret_cast<p::byte*>(const_cast<dt::IntervalOwnedValueV3*>(&value));
  auto overlap = dt::EncodeCanonicalIntervalComponentIntoNoAllocV3(value, object_bytes, 16);
  Check(!overlap.ok() && Diagnostic(overlap, "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID") && overlap.bytes_written == 0, "component complete overlap");
  overlap = dt::EncodeCanonicalIntervalComponentIntoNoAllocV3(value, object_bytes + 1, 16);
  Check(!overlap.ok() && Diagnostic(overlap, "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID") && overlap.bytes_written == 0, "component partial overlap");
  overlap = dt::HashIntervalValueIntoNoAllocV3(value, object_bytes, 32);
  Check(!overlap.ok() && Diagnostic(overlap, "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID") && overlap.bytes_written == 0, "hash complete overlap");
  overlap = dt::HashIntervalValueIntoNoAllocV3(value, object_bytes + 1, 32);
  Check(!overlap.ok() && Diagnostic(overlap, "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID") && overlap.bytes_written == 0, "hash partial overlap");
  auto text_overlap = dt::RenderCanonicalIntervalIntoNoAllocV3(value, reinterpret_cast<char*>(object_bytes), 63);
  Check(!text_overlap.ok() && Diagnostic(text_overlap, "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID") && text_overlap.bytes_written == 0,
        "render complete overlap");
  text_overlap = dt::RenderCanonicalIntervalIntoNoAllocV3(value, reinterpret_cast<char*>(object_bytes + 1), 63);
  Check(!text_overlap.ok() && Diagnostic(text_overlap, "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID") && text_overlap.bytes_written == 0,
        "render partial overlap");

  auto budget = dt::EncodeCanonicalIntervalComponentV3(value, dt::IntervalExecutionControlV3{15});
  Check(!budget.ok() && Diagnostic(budget, "RESOURCE.BUDGET_EXCEEDED") && budget.bytes.empty(), "owned component budget no publication");
  allocation_probe::fail_next = true; const auto calls_before = allocation_probe::calls;
  auto allocation = dt::EncodeCanonicalIntervalComponentV3(value);
  Check(!allocation.ok() && Diagnostic(allocation, "RESOURCE.BUDGET_EXCEEDED") && allocation.bytes.empty() &&
        allocation_probe::calls == calls_before + 1 && !allocation_probe::fail_next, "owned component allocation failure");

  const auto* character_identity = Identity(dt::CanonicalTypeId::character);
  Check(character_identity != nullptr, "current character identity");
  const auto character_descriptor = Descriptor(dt::CanonicalTypeId::character);
  const auto interval_descriptor = Descriptor(dt::CanonicalTypeId::interval);
  dt::IntervalCastRequestV3 outgoing;
  outgoing.one_based_policy_row = 13; outgoing.context = dt::DatatypeCastContext::explicit_cast;
  outgoing.interval_source = &value; outgoing.scalar_target = dt::CanonicalTypeId::character;
  outgoing.scalar_target_identity = character_identity; outgoing.scalar_target_descriptor = character_descriptor;
  outgoing.use_character_output_buffer = true; outgoing.character_output = text.data(); outgoing.character_output_capacity = 63;
  text.fill(static_cast<char>(0xa5)); auto cast = dt::CastIntervalValueV3(outgoing);
  Check(cast.ok() && cast.used_character_output_buffer && cast.bytes_required == 63 && cast.bytes_written == 63,
        "interval to character exact 63");
  text.fill(static_cast<char>(0xa5)); outgoing.character_output_capacity = 62; cast = dt::CastIntervalValueV3(outgoing);
  Check(!cast.ok() && Diagnostic(cast, "CTB.TEXT.LENGTH_EXCEEDED") && cast.bytes_written == 0 && text == text_before,
        "interval to character one short unchanged");
  outgoing.character_output_capacity = 63; outgoing.character_output = reinterpret_cast<char*>(object_bytes);
  cast = dt::CastIntervalValueV3(outgoing);
  Check(!cast.ok() && Diagnostic(cast, "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID") && cast.bytes_written == 0,
        "interval to character complete overlap");
  outgoing.character_output = reinterpret_cast<char*>(object_bytes + 1); cast = dt::CastIntervalValueV3(outgoing);
  Check(!cast.ok() && Diagnostic(cast, "CTI.TEMPORAL.CANONICAL_ENCODING_INVALID") && cast.bytes_written == 0,
        "interval to character partial overlap");
  outgoing.character_output = text.data(); control = CancelFinal(1, cancel); outgoing.control = control;
  text.fill(static_cast<char>(0xa5)); cast = dt::CastIntervalValueV3(outgoing);
  Check(!cast.ok() && Diagnostic(cast, "PROCESS.CANCELLED") && cast.bytes_written == 0 && text == text_before,
        "interval to character final cancel unchanged");

  dt::DatatypeOperationValue character_value;
  character_value.type_id = dt::CanonicalTypeId::character; character_value.is_null = false;
  character_value.encoded_value = rendered.text; character_value.descriptor = character_descriptor;
  dt::IntervalCastRequestV3 incoming;
  incoming.one_based_policy_row = 124; incoming.context = dt::DatatypeCastContext::explicit_cast;
  incoming.scalar_source = &character_value; incoming.scalar_source_identity = character_identity;
  incoming.interval_target = &profile; incoming.interval_target_descriptor = &interval_descriptor;
  cast = dt::CastIntervalValueV3(incoming);
  Check(cast.ok() && cast.produced_interval && cast.interval_value.months == value.months &&
        cast.interval_value.civil_days == value.civil_days && cast.interval_value.fixed_nanoseconds == value.fixed_nanoseconds,
        "character to interval exact 63");
  character_value.encoded_value = overlong; cast = dt::CastIntervalValueV3(incoming);
  Check(!cast.ok() && Diagnostic(cast, "CTB.TEXT.LENGTH_EXCEEDED") && !cast.produced_interval && cast.interval_value.profile == nullptr,
        "character to interval over maximum no publication");
  character_value.encoded_value = rendered.text; control = CancelFinal(1, cancel); incoming.control = control;
  cast = dt::CastIntervalValueV3(incoming);
  Check(!cast.ok() && Diagnostic(cast, "PROCESS.CANCELLED") && !cast.produced_interval && cast.interval_value.profile == nullptr,
        "character to interval final cancel no publication");

  auto small = Value(profile); auto arithmetic = dt::AddIntervalCheckedV3(small, small);
  Check(arithmetic.ok() && arithmetic.value.months == 6 && arithmetic.value.civil_days == -10 &&
        arithmetic.value.fixed_nanoseconds == 14, "arithmetic exact publication");
  arithmetic = dt::NegateIntervalCheckedV3(value);
  Check(!arithmetic.ok() && Diagnostic(arithmetic, "CTI.TEMPORAL.RANGE_EXCEEDED") && arithmetic.value.profile == nullptr,
        "arithmetic overflow no publication");
  control = CancelFinal(1, cancel); arithmetic = dt::AddIntervalCheckedV3(small, small, true, control);
  Check(!arithmetic.ok() && Diagnostic(arithmetic, "PROCESS.CANCELLED") && arithmetic.value.profile == nullptr,
        "arithmetic final cancel no publication");

  std::array<std::int32_t, 8> months{}; std::array<std::int32_t, 8> days{}; std::array<std::int64_t, 8> nanos{};
  std::array<p::byte, 1> bitmap{};
  auto batch = dt::MaterializeIntervalBatchV3(profile, months, days, nanos, bitmap);
  Check(batch.ok() && batch.batch.months.size() == 8 && batch.batch.civil_days.size() == 8 &&
        batch.batch.fixed_nanoseconds.size() == 8 && batch.batch.null_bitmap_lsb0.size() == 1, "batch exact 129 bytes");
  dt::IntervalExecutionControlV3 short_batch; short_batch.maximum_allocation_bytes = 128;
  batch = dt::MaterializeIntervalBatchV3(profile, months, days, nanos, bitmap, short_batch);
  Check(!batch.ok() && Diagnostic(batch, "RESOURCE.BUDGET_EXCEEDED") && batch.batch.months.empty() && batch.batch.civil_days.empty() &&
        batch.batch.fixed_nanoseconds.empty() && batch.batch.null_bitmap_lsb0.empty(), "batch one short no publication");
  control = CancelFinal(6, cancel); batch = dt::MaterializeIntervalBatchV3(profile, months, days, nanos, bitmap, control);
  Check(!batch.ok() && Diagnostic(batch, "PROCESS.CANCELLED") && batch.batch.months.empty() && batch.batch.civil_days.empty() &&
        batch.batch.fixed_nanoseconds.empty() && batch.batch.null_bitmap_lsb0.empty(), "batch final cancel no publication");
  allocation_probe::fail_next = true; batch = dt::MaterializeIntervalBatchV3(profile, months, days, nanos, bitmap);
  Check(!batch.ok() && Diagnostic(batch, "RESOURCE.BUDGET_EXCEEDED") && batch.batch.months.empty() &&
        batch.batch.civil_days.empty() && batch.batch.fixed_nanoseconds.empty() && batch.batch.null_bitmap_lsb0.empty() &&
        !allocation_probe::fail_next, "batch allocation failure no publication");

  const auto sbdval = dt::EncodeIntervalSbdvalComposedV3(value, true); Check(sbdval.ok() && sbdval.bytes.size() == 48, "SBDVAL exact 48");
  dt::IntervalExecutionControlV3 short_owned; short_owned.maximum_allocation_bytes = 47;
  auto owned = dt::EncodeIntervalSbdvalComposedV3(value, true, short_owned);
  Check(!owned.ok() && Diagnostic(owned, "RESOURCE.BUDGET_EXCEEDED") && owned.bytes.empty(), "SBDVAL one short");
  control = CancelFinal(2, cancel); owned = dt::EncodeIntervalSbdvalComposedV3(value, true, control);
  Check(!owned.ok() && Diagnostic(owned, "PROCESS.CANCELLED") && owned.bytes.empty(), "SBDVAL final cancel");
  allocation_probe::fail_next = true; owned = dt::EncodeIntervalSbdvalComposedV3(value, true);
  Check(!owned.ok() && Diagnostic(owned, "RESOURCE.BUDGET_EXCEEDED") && owned.bytes.empty() && !allocation_probe::fail_next,
        "SBDVAL allocation failure");
  const auto sbdpv = dt::EncodeIntervalSbdpvComposedV3(value, true); Check(sbdpv.ok() && sbdpv.bytes.size() == 40, "SBDPV exact 40");
  short_owned.maximum_allocation_bytes = 39; owned = dt::EncodeIntervalSbdpvComposedV3(value, true, short_owned);
  Check(!owned.ok() && Diagnostic(owned, "RESOURCE.BUDGET_EXCEEDED") && owned.bytes.empty(), "SBDPV one short");
  control = CancelFinal(2, cancel); owned = dt::EncodeIntervalSbdpvComposedV3(value, true, control);
  Check(!owned.ok() && Diagnostic(owned, "PROCESS.CANCELLED") && owned.bytes.empty(), "SBDPV final cancel");
  allocation_probe::fail_next = true; owned = dt::EncodeIntervalSbdpvComposedV3(value, true);
  Check(!owned.ok() && Diagnostic(owned, "RESOURCE.BUDGET_EXCEEDED") && owned.bytes.empty() && !allocation_probe::fail_next,
        "SBDPV allocation failure");

  dt::IntervalIndexProjectionRequestV3 equality_request;
  equality_request.compatibility = dt::LookupIntervalIndexCompatibilityIdentityV3(dt::IntervalIndexFamilyV3::hash);
  equality_request.mode = dt::IntervalProjectionModeV3::equality_hash; equality_request.value = &value;
  auto projected = dt::ProjectIntervalIndexValueV3(equality_request);
  Check(projected.ok() && projected.bytes.size() == 160, "equality projection exact 160");
  equality_request.control.maximum_allocation_bytes = 159; projected = dt::ProjectIntervalIndexValueV3(equality_request);
  Check(!projected.ok() && Diagnostic(projected, "RESOURCE.BUDGET_EXCEEDED") && projected.bytes.empty(), "equality projection one short");
  equality_request.control = CancelFinal(2, cancel); projected = dt::ProjectIntervalIndexValueV3(equality_request);
  Check(!projected.ok() && Diagnostic(projected, "PROCESS.CANCELLED") && projected.bytes.empty(), "equality projection final cancel");
  equality_request.control = {}; allocation_probe::fail_next = true; projected = dt::ProjectIntervalIndexValueV3(equality_request);
  Check(!projected.ok() && Diagnostic(projected, "RESOURCE.BUDGET_EXCEEDED") && projected.bytes.empty() && !allocation_probe::fail_next,
        "equality projection allocation failure");

  const auto covering = dt::EncodeIntervalCoveringValueV3(value); Check(covering.ok() && covering.bytes.size() == 17, "covering exact 17");
  short_owned.maximum_allocation_bytes = 16; owned = dt::EncodeIntervalCoveringValueV3(value, short_owned);
  Check(!owned.ok() && Diagnostic(owned, "RESOURCE.BUDGET_EXCEEDED") && owned.bytes.empty(), "covering one short");
  control = CancelFinal(2, cancel); owned = dt::EncodeIntervalCoveringValueV3(value, control);
  Check(!owned.ok() && Diagnostic(owned, "PROCESS.CANCELLED") && owned.bytes.empty(), "covering final cancel");
  allocation_probe::fail_next = true; owned = dt::EncodeIntervalCoveringValueV3(value);
  Check(!owned.ok() && Diagnostic(owned, "RESOURCE.BUDGET_EXCEEDED") && owned.bytes.empty() && !allocation_probe::fail_next,
        "covering allocation failure");
  const auto backup = dt::EncodeIntervalBackupTupleV3(value); Check(backup.ok() && backup.bytes.size() == 376, "backup exact 376");
  short_owned.maximum_allocation_bytes = 375; owned = dt::EncodeIntervalBackupTupleV3(value, short_owned);
  Check(!owned.ok() && Diagnostic(owned, "RESOURCE.BUDGET_EXCEEDED") && owned.bytes.empty(), "backup one short");
  control = CancelFinal(2, cancel); owned = dt::EncodeIntervalBackupTupleV3(value, control);
  Check(!owned.ok() && Diagnostic(owned, "PROCESS.CANCELLED") && owned.bytes.empty(), "backup final cancel");
  allocation_probe::fail_next = true; owned = dt::EncodeIntervalBackupTupleV3(value);
  Check(!owned.ok() && Diagnostic(owned, "RESOURCE.BUDGET_EXCEEDED") && owned.bytes.empty() && !allocation_probe::fail_next,
        "backup allocation failure");

  for (unsigned iteration = 0; iteration < 4096; ++iteration) {
    const auto encoded = dt::EncodeCanonicalIntervalComponentV3(value);
    Check(encoded.ok() && encoded.bytes.size() == 16, "4096 publication cycle encode");
    const auto roundtrip = dt::DecodeCanonicalIntervalComponentNoAllocV3(*profile, dt::IntervalValueStateV3::value, true, encoded.bytes);
    Check(roundtrip.ok() && roundtrip.value.profile == profile.get(), "4096 publication cycle pinned profile");
  }
}

void ScrubCoverage(const std::shared_ptr<const dt::IntervalValidatedProfileHandleV3>& profile) {
  const auto value = Value(profile); ScrubTracker tracker; dt::IntervalExecutionControlV3 control;
  control.observe_scrubbed = ObserveScrub; control.scrub_observer_context = &tracker;
  Check(dt::ValidateIntervalProfileHandleV3(*profile, control).ok(), "scrub profile");
  const auto component = dt::EncodeCanonicalIntervalComponentV3(value, control); Check(component.ok(), "scrub component encode");
  Check(dt::DecodeCanonicalIntervalComponentNoAllocV3(*profile, dt::IntervalValueStateV3::value, true, component.bytes, control).ok(), "scrub component decode");
  Check(dt::RenderCanonicalIntervalV3(value, control).ok(), "scrub render"); Check(dt::HashIntervalValueV3(value, control).ok(), "scrub hash");
  const auto sbdval = dt::EncodeIntervalSbdvalComposedV3(value, true, control);
  const auto sbdpv = dt::EncodeIntervalSbdpvComposedV3(value, true, control);
  Check(sbdval.ok() && sbdpv.ok(), "scrub composed encode");
  Check(dt::DecodeIntervalSbdvalComposedNoAllocV3(*profile, true, sbdval.bytes, control).ok() &&
        dt::DecodeIntervalSbdpvComposedNoAllocV3(*profile, true, sbdpv.bytes, control).ok(), "scrub composed decode");
  const auto covering = dt::EncodeIntervalCoveringValueV3(value, control);
  Check(covering.ok() && dt::DecodeIntervalCoveringValueNoAllocV3(*profile, true, covering.bytes, control).ok(), "scrub covering");
  dt::IntervalIndexProjectionRequestV3 projection;
  projection.compatibility = dt::LookupIntervalIndexCompatibilityIdentityV3(dt::IntervalIndexFamilyV3::hash);
  projection.mode = dt::IntervalProjectionModeV3::equality_hash; projection.value = &value; projection.control = control;
  Check(dt::ProjectIntervalIndexValueV3(projection).ok(), "scrub equality projection");
  const auto backup = dt::EncodeIntervalBackupTupleV3(value, control);
  Check(backup.ok() && dt::DecodeIntervalBackupTupleNoAllocV3(*profile, true, backup.bytes, control).ok(), "scrub backup");
  std::array<std::int32_t, 1> months{1}, days{2}; std::array<std::int64_t, 1> nanos{3}; std::array<p::byte, 1> bitmap{};
  Check(dt::MaterializeIntervalBatchV3(profile, months, days, nanos, bitmap, control).ok(), "scrub batch");
  CancelState cancelled;
  auto cancelled_control = control; cancelled_control.cancelled = CancelAt; cancelled_control.cancellation_context = &cancelled;
  cancelled = {0, 2}; Check(!dt::EncodeCanonicalIntervalComponentV3(value, cancelled_control).ok(), "scrub component owned failure");
  cancelled = {0, 2}; Check(!dt::EncodeIntervalSbdvalComposedV3(value, true, cancelled_control).ok(), "scrub SBDVAL owned failure");
  cancelled = {0, 2}; Check(!dt::EncodeIntervalSbdpvComposedV3(value, true, cancelled_control).ok(), "scrub SBDPV owned failure");
  cancelled = {0, 2}; Check(!dt::EncodeIntervalCoveringValueV3(value, cancelled_control).ok(), "scrub covering owned failure");
  cancelled = {0, 2}; projection.control = cancelled_control;
  Check(!dt::ProjectIntervalIndexValueV3(projection).ok(), "scrub projection owned failure");
  cancelled = {0, 5};
  Check(!dt::MaterializeIntervalBatchV3(profile, months, days, nanos, bitmap, cancelled_control).ok(), "scrub batch owned failure");

  // These are literal generation-1 requirements. Statistics-only classes 23-24
  // are covered by the statistics corpus after its receiving-facts API lands.
  const std::array<unsigned, 31> expected_count{{
      110,850,110,50,50,50,50,12,2,1,1,1,5,10,1,3,2,1,3,2,1,6,3,0,0,2,2,1,1,1,1}};
  const std::array<std::uint64_t, 31> expected_extent{{
      3520,217600,14080,30400,17200,1600,1600,192,32,16,64,63,665,320,32,144,
      32,48,120,32,40,448,51,0,0,752,177,4,4,8,1}};
  for (unsigned ordinal = 0; ordinal < 31; ++ordinal) {
    current_case = ordinal;
    Check(tracker.count[ordinal] == expected_count[ordinal], "literal scrub class multiplicity");
    Check(tracker.extent[ordinal] == expected_extent[ordinal], "literal scrub byte extent");
  }
  Check(tracker.all_zero, "all observed scrub bytes zeroed");
}

